insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000000c', 'en', null, 'Introduction to Nutrition', 'A first tour of how food fuels the body — energy and macronutrients, carbohydrates, proteins, fats, vitamins and minerals, and how to read a label. Structure adapted from OpenStax Nutrition (CC BY 4.0). Educational only, not medical advice.', null, 'daily_life', 12, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000000c', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"A ''Calorie'' on a food label is a unit of…","options":["weight","energy","volume","sugar"],"answer":1,"explanation":"A Calorie measures food energy — see ''Energy and macronutrients''."},{"prompt":"The three macronutrients that provide energy are carbohydrates, fats, and…","options":["vitamins","protein","water","fiber"],"answer":1,"explanation":"Carbs, fats, and protein supply calories; vitamins and water do not — see ''Energy and macronutrients''."},{"prompt":"One gram of fat provides about how many calories?","options":["4","7","9","0"],"answer":2,"explanation":"Fat packs ~9 cal/g, more than double carbs or protein — see ''Fats''."},{"prompt":"The body''s preferred quick source of energy is…","options":["protein","carbohydrate","vitamins","minerals"],"answer":1,"explanation":"Glucose from carbohydrate fuels the brain and muscles first — see ''Carbohydrates''."},{"prompt":"The main structural role of dietary protein is to…","options":["store fat","build and repair tissue","add sweetness","provide fiber"],"answer":1,"explanation":"Amino acids from protein build muscle, enzymes, and more — see ''Proteins''."},{"prompt":"Vitamins and minerals are called micronutrients because they…","options":["are less important","are needed in small amounts","contain no atoms","provide most calories"],"answer":1,"explanation":"''Micro'' = needed in small amounts, but still essential — see ''Key terms''."},{"prompt":"Digestion of food mostly begins in the mouth and continues in the…","options":["lungs","stomach and small intestine","kidneys","skin"],"answer":1,"explanation":"Mechanical and chemical breakdown continues down the digestive tract — see ''Key terms''."},{"prompt":"On a Nutrition Facts label, the ''% Daily Value'' helps you judge whether a nutrient amount is…","options":["organic","high or low per serving","vegan","gluten-free"],"answer":1,"explanation":"5% DV is low, 20% DV is high, per serving — see ''Healthy eating patterns and labels''."}]}'::jsonb, null, 10),
  (2, 'Energy and the macronutrients', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what a food Calorie measures and calculate the calories in a food from its grams of carbohydrate, protein, and fat. Warm-up: from the diagnostic, which single macronutrient carries the most calories per gram?"},{"heading":"The idea","text":"Food gives the body *energy*, measured in *Calories* (kilocalories). Only three nutrients supply that energy — the *macronutrients*: *carbohydrate*, *protein*, and *fat*. Their energy density is fixed and worth memorizing: carbohydrate and protein each give about 4 calories per gram, and fat gives about 9 calories per gram. (Alcohol, though not a nutrient, adds about 7.) Water, vitamins, and minerals carry zero calories — they matter for other reasons."},{"heading":"Worked example","text":"A granola bar lists 20 g carbohydrate, 5 g protein, and 7 g fat. Multiply by the 4-4-9 rule: carbs = 20 × 4 = 80 cal; protein = 5 × 4 = 20 cal; fat = 7 × 9 = 63 cal. Total = 80 + 20 + 63 = 163 calories. Notice the 7 grams of fat contribute more energy than the 20 grams of carbohydrate — because fat is more than twice as energy-dense."},{"heading":"Your turn","text":"Compute total calories using 4-4-9. (1) 30 g carb, 0 g protein, 0 g fat. (2) 10 g carb, 10 g protein, 10 g fat. (3) A food that is 0 g carb, 25 g protein, 5 g fat. (4) Which has more calories: 10 g of fat or 20 g of carbohydrate? Answers: (1) 120 cal; (2) 40 + 40 + 90 = 170 cal; (3) 100 + 45 = 145 cal; (4) 10 g fat = 90 cal beats 20 g carb = 80 cal."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking vitamins or water provide calories — they do not. Mistake: assuming ''more grams'' always means ''more calories'' — grams of fat count far more than grams of carbohydrate. Exit: (a) How many calories are in 1 g of protein? (b) A snack has 0 g carb, 0 g protein, 12 g fat — how many calories? Answers: (a) about 4; (b) 12 × 9 = 108 calories."}]}'::jsonb, 'Energy providers: carbs 4, protein 4, fat 9 calories per gram. Memorize 4-4-9.', 12),
  (3, 'Carbohydrates: the body''s quick fuel', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish simple from complex carbohydrates and explain the role of fiber. Warm-up: which macronutrient does the brain rely on first for energy?"},{"heading":"The idea","text":"*Carbohydrates* are the body''s main quick fuel; digestion breaks most of them into *glucose*, the sugar that powers the brain and muscles. *Simple carbohydrates* (sugars like those in candy or juice) raise blood glucose fast. *Complex carbohydrates* (starches in bread, rice, beans) release glucose more slowly. *Fiber* is a special complex carbohydrate the body cannot digest — it passes through, supporting digestion and helping you feel full, while adding little usable energy."},{"heading":"Worked example","text":"Two 200-calorie snacks: a glass of soda (nearly all simple sugar, no fiber) versus a bowl of oatmeal (complex starch plus ~4 g fiber). Same calories by the 4-4-9 rule — carbohydrate is 4 cal/g either way — but the oatmeal''s fiber slows digestion, so glucose rises gradually and you stay full longer. Energy count equal; the body''s experience is not."},{"heading":"Your turn","text":"Classify simple or complex, and answer. (1) table sugar; (2) lentils; (3) white bread; (4) the fiber in an apple; (5) how many calories in 50 g of carbohydrate? (6) Does fiber give you much usable energy? Answers: (1) simple; (2) complex; (3) complex (starch); (4) complex, indigestible; (5) 50 × 4 = 200 calories; (6) no — it is largely indigestible."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing ''all carbs are bad'' — complex carbs and fiber are staples of healthy eating. Mistake: thinking fiber is a separate nutrient from carbohydrate (it is a type of carbohydrate). Exit: (a) What sugar do carbs break down into? (b) Name one benefit of fiber. Answers: (a) glucose; (b) it aids digestion and helps you feel full."}]}'::jsonb, 'Simple = sugars (fast); complex = starch + fiber (slow). Fiber is carbohydrate you don''t digest.', 12),
  (4, 'Fats: concentrated energy', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why fat is the most energy-dense macronutrient and tell healthier fats from less healthy ones. Warm-up: how many calories does one gram of fat provide?"},{"heading":"The idea","text":"*Fats* (lipids) are the most *energy-dense* macronutrient at about 9 calories per gram. They store energy, cushion organs, and help the body absorb fat-soluble vitamins (A, D, E, K). Type matters: *unsaturated fats* (olive oil, nuts, fish) support heart health; *saturated fats* (butter, fatty meat) are fine in moderation; *trans fats* (in some processed foods) are best avoided. Fat is not the enemy — it is essential — but its density means small amounts add up fast."},{"heading":"Worked example","text":"A tablespoon of olive oil is about 14 g of pure fat. Calories = 14 × 9 = 126 calories from one spoon. Compare 14 g of pure carbohydrate: 14 × 4 = 56 calories. Same weight, but the oil carries more than twice the energy — this is why a ''light drizzle'' of oil adds more calories than it looks."},{"heading":"Your turn","text":"Use 9 cal/g and classify the fat type. (1) Calories in 20 g of fat? (2) Calories in 5 g of fat? (3) Olive oil — saturated or unsaturated? (4) Butter — saturated or unsaturated? (5) Which fat should you avoid? (6) Which vitamins need fat to be absorbed? Answers: (1) 180 cal; (2) 45 cal; (3) unsaturated; (4) saturated; (5) trans fat; (6) A, D, E, and K."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking all fat is unhealthy — unsaturated fats are beneficial and some fat is essential. Mistake: forgetting fat''s density when estimating calories. Exit: (a) Calories in 10 g of fat? (b) Name a source of healthy unsaturated fat. Answers: (a) 90 calories; (b) olive oil, nuts, or fish."}]}'::jsonb, 'Fat = 9 cal/g, the most energy-dense. Unsaturated (plant/fish) generally healthier than saturated; avoid trans fats.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Using the 4-4-9 rule, 10 g of carbohydrate provides…","options":["9 calories","40 calories","90 calories","100 calories"],"answer":1,"explanation":"Carbohydrate is 4 cal/g, so 10 × 4 = 40."},{"prompt":"The most energy-dense macronutrient is…","options":["carbohydrate","protein","fat","fiber"],"answer":2,"explanation":"Fat provides ~9 cal/g."},{"prompt":"Which is a complex carbohydrate?","options":["table sugar","soda","brown rice","honey"],"answer":2,"explanation":"Starchy grains like brown rice are complex carbs."},{"prompt":"Fiber is best described as…","options":["a type of protein","a carbohydrate the body cannot digest","a saturated fat","a vitamin"],"answer":1,"explanation":"Fiber is an indigestible complex carbohydrate."},{"prompt":"A tablespoon of oil (~14 g fat) contains about…","options":["14 calories","56 calories","126 calories","9 calories"],"answer":2,"explanation":"14 × 9 ≈ 126 calories."},{"prompt":"Which fat is best avoided?","options":["unsaturated fat","trans fat","olive oil","fat in fish"],"answer":1,"explanation":"Trans fats are the least healthy type."}]}'::jsonb, null, 8),
  (6, 'Proteins: the body''s building blocks', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe what proteins are made of and their main job in the body. Warm-up: besides energy, what is protein most needed for?"},{"heading":"The idea","text":"*Proteins* are chains of *amino acids* and are the body''s main building material — for muscle, skin, enzymes, and antibodies. Of the twenty amino acids, nine are *essential*, meaning food must supply them. A *complete protein* contains all nine (most animal foods; also soy and quinoa), while many plant foods are *incomplete* but *complement* each other — rice plus beans together supply what neither has alone. Protein also provides energy at about 4 calories per gram, the same as carbohydrate."},{"heading":"Worked example","text":"A chicken breast lists 30 g protein, 0 g carb, 3 g fat. Calories = (30 × 4) + (3 × 9) = 120 + 27 = 147 calories, and it is a complete protein. Now a cup of rice (incomplete) plus a cup of beans (incomplete) eaten together supply all nine essential amino acids — proof that complementary plant proteins can match animal protein for building tissue."},{"heading":"Your turn","text":"(1) Protein is built from what smaller units? (2) How many essential amino acids are there? (3) Is beef a complete or incomplete protein? (4) Name a plant pair that complements. (5) Calories in 25 g of protein? (6) Which packs more calories per gram, protein or fat? Answers: (1) amino acids; (2) nine; (3) complete; (4) rice and beans; (5) 25 × 4 = 100 cal; (6) fat (9 vs 4)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking only meat can build muscle — combined plant proteins work well. Mistake: assuming more protein always means fewer calories (protein still carries 4 cal/g). Exit: (a) What makes a protein ''complete''? (b) Calories in 15 g of protein? Answers: (a) it contains all nine essential amino acids; (b) 15 × 4 = 60 calories."}]}'::jsonb, 'Protein = 4 cal/g. Made of amino acids; ''complete'' proteins have all essential ones.', 12),
  (7, 'Healthy eating patterns and reading labels', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read a Nutrition Facts label correctly and describe what a balanced eating pattern looks like. Warm-up: on a label, which number must you check before every other number?"},{"heading":"The idea","text":"A healthy *eating pattern* balances all the nutrients across the day: plenty of vegetables, fruits, and whole grains; lean proteins; healthy fats; and limited added sugar, saturated fat, and sodium. To apply this at the store, read the *Nutrition Facts* label. Always start with the *serving size* — every listed number is per serving, and a package may hold several. Then use the *% Daily Value*: about *5% DV or less is low* and *20% DV or more is high* for a nutrient. Aim high for fiber and vitamins, lower for added sugars, saturated fat, and sodium."},{"heading":"Worked example","text":"A chip bag says: serving size 1 oz, servings per container 3, 150 calories, 15% DV sodium per serving. If you eat the whole bag you get 3 × 150 = 450 calories and 3 × 15% = 45% DV of sodium — nearly half a day''s sodium at 45% DV, which is ''high''. The label looked modest only because it counted one of three servings."},{"heading":"Your turn","text":"A cereal label: serving size 1 cup, 8 g fiber (28% DV), 12 g added sugar. (1) What do you check first? (2) Is 28% DV fiber high or low? (3) You pour 2 cups — how many grams of added sugar? (4) Is high fiber something to seek or limit? (5) Is 4% DV sodium high or low? (6) Name one food group a healthy pattern emphasizes. Answers: (1) serving size; (2) high; (3) 24 g; (4) seek; (5) low; (6) vegetables, fruits, or whole grains."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading the calories without noticing the package holds several servings. Mistake: treating ''low fat'' or ''natural'' claims as proof a food is healthy — check the actual label. Exit: (a) What does 20% DV or more mean? (b) The first line to read on any label is…? Answers: (a) that nutrient is high per serving; (b) the serving size."}]}'::jsonb, 'On labels: check serving size first, then use 5% DV = low, 20% DV = high.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"Calorie","translation":"a unit measuring the energy food provides","example":"A slice of bread has about 80 Calories."},{"term":"macronutrient","translation":"an energy-providing nutrient — carbohydrate, protein, or fat","example":"Each macronutrient has a fixed calories-per-gram value."},{"term":"micronutrient","translation":"a vitamin or mineral the body needs in small amounts","example":"Iron and vitamin C are micronutrients that carry no calories."},{"term":"fiber","translation":"a complex carbohydrate the body cannot digest","example":"Fiber aids digestion and helps you feel full."},{"term":"amino acid","translation":"the building block that links up to form a protein","example":"Nine amino acids are essential and must come from food."},{"term":"digestion","translation":"the breakdown of food into absorbable nutrients, beginning in the mouth","example":"Digestion turns starch into glucose the body can absorb."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Protein is assembled from smaller units called…","options":["glucose molecules","amino acids","fatty acids","minerals"],"answer":1,"explanation":"Amino acids chain together to form proteins."},{"prompt":"A ''complete'' protein is one that…","options":["has zero fat","contains all nine essential amino acids","comes only from plants","has the most calories"],"answer":1,"explanation":"Complete proteins supply every essential amino acid."},{"prompt":"Vitamins and minerals are grouped as…","options":["macronutrients","micronutrients","fibers","calories"],"answer":1,"explanation":"They are needed in small amounts and carry no calories."},{"prompt":"On a Nutrition Facts label you should read … first.","options":["the calories","the serving size","the sodium","the brand"],"answer":1,"explanation":"Every value is per serving, so serving size comes first."},{"prompt":"A nutrient at 20% DV or more per serving is considered…","options":["low","high","trans fat","calorie-free"],"answer":1,"explanation":"20% DV or more is ''high''; 5% or less is ''low''."},{"prompt":"A healthy eating pattern emphasizes vegetables, fruits, whole grains and limits…","options":["fiber and vitamins","added sugar, saturated fat, and sodium","water and protein","all carbohydrates"],"answer":1,"explanation":"Balance nutrients; limit added sugar, saturated fat, and sodium."}]}'::jsonb, null, 8),
  (10, 'Applied project: analyze and improve a day of your meals', 'writing', '{"sections":[{"heading":"The task","text":"Take one real day of your own eating — breakfast, lunch, dinner, and snacks — and analyze it using the tools from this course. This is an educational exercise, not medical or dietary advice; the goal is to practice reasoning about food, not to prescribe a diet."},{"heading":"Milestones","text":"1) List what you ate and, using labels or estimates, note grams of carbohydrate, protein, and fat for a few items. 2) Apply the 4-4-9 rule to estimate calories for at least two foods. 3) Identify where each macronutrient came from, and spot one source of fiber and one micronutrient. 4) Propose one realistic swap that improves balance — for example, a complex carb for a simple one, or an unsaturated fat for a saturated one — and explain in a sentence why it helps."},{"heading":"Self-check rubric","text":"✔ You recorded real foods with rough macronutrient grams. ✔ You correctly used 4-4-9 to estimate calories for two foods. ✔ You named a fiber source and a micronutrient. ✔ Your proposed swap is realistic and you justified it with a nutrition concept from the course. If all four are true, you can now read your own plate like a nutrition student."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000000c' and l.position = v.pos
);
